policy:
policy CleaningStockPolicy {
  allow read Supplies(supply, qty, minimum, reorder_qty, supplier, cost)
  allow supplier Supplies.supplier
  limit order $250 per action
  limit order $1000 per day
}

program:
procedure CleaningReorder {
  about "Reorder supplies below their minimum"
  policy CleaningStockPolicy
  sheet Supplies "Supplies" { supply: Text, qty: Number, minimum: Number, reorder_qty: Number, supplier: Text, cost: Money }
  trigger every day at 08:00

  let all = fetch Supplies
  let low = filter all where qty < minimum
  for each i in low up to 4 {
    let cost = i.reorder_qty * i.cost
    if cost > $250.00 {
      notify owner "Reorder of {i.supply} would cost {cost}, over the $250 limit."
      skip
    }
    order "{i.reorder_qty} x {i.supply}" from i.supplier cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.supply}"
  }
}

